using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using SportRace.Domain.Entities; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.AgeGroups;
public class EditModel : PageModel { private readonly IHttpClientFactory _factory; [BindProperty] public AgeGroup AgeGroup {get;set;}=new(); public EditModel(IHttpClientFactory factory)=>_factory=factory; public async Task<IActionResult> OnGetAsync(int id){var a=await _factory.CreateClient("SportRaceApi1").GetFromJsonAsync<AgeGroup>($"api/agegroups/{id}"); if(a is null)return NotFound(); AgeGroup=a; return Page();} public async Task<IActionResult> OnPostAsync(){if(AgeGroup.MaxAge<AgeGroup.MinAge){ModelState.AddModelError("","Невалиден диапазон.");return Page();} var r=await _factory.CreateClient("SportRaceApi1").PutAsJsonAsync($"api/agegroups/{AgeGroup.Id}",AgeGroup); return r.IsSuccessStatusCode?RedirectToPage("Index"):Page();}}
